import{nameIs}from"../rule.js";const passThroughMessage=e=>e.message,passThroughHint=e=>e.hint,SANDBOX_RULES=[{id:`sandbox-docker-cli-missing`,name:`Docker CLI not found`,tags:[`sandbox`,`config`],when:nameIs(`DockerUnavailableError`),message:passThroughMessage,hint:passThroughHint},{id:`sandbox-docker-daemon-unreachable`,name:`Docker daemon unreachable`,tags:[`sandbox`,`config`],when:nameIs(`DockerDaemonUnavailableError`),message:passThroughMessage,hint:passThroughHint},{id:`sandbox-provisioning-failed`,name:`Sandbox provisioning failed`,tags:[`sandbox`],when:nameIs(`MicrosandboxDiagnosticError`),message:passThroughMessage,hint:passThroughHint}];export{SANDBOX_RULES};